    /** 首个最长命中；无命中返回 null（调用方回 fallback 上游原类）。 */
    fun refine(name: String): String? {
        var best: Pair<String, String>? = null
        for ((kw, cat) in RULES) {
            if (kw.isNotEmpty() && kw in name && (best == null || kw.length > best.first.length)) {
                best = kw to cat
            }
        }
        return best?.second
    }
}
